sysdrills/14-observability-and-telemetry.solution:
export function tracesKeptPerSec(qps, samplePermille) {
  return (qps * samplePermille) / 1000;
}

export function samplePermilleForBudget(budgetTracesPerDay, qps) {
  return (budgetTracesPerDay * 1000) / (qps * 86400);
}

