sysdrills/14-observability-and-telemetry.solution:
export function seriesCount(labelCardinalities) {
  return labelCardinalities.reduce((s, x) => s * x, 1);
}

export function monthlySeriesCents(labelCardinalities, centsPerSeries) {
  return seriesCount(labelCardinalities) * centsPerSeries;
}

