export function tieredMonthlyCents(gbPerDay, hotDays, hotCentsPerGb, coldDays, coldCentsPerGb) {
  return gbPerDay * (hotDays * hotCentsPerGb + coldDays * coldCentsPerGb);
}

export function savedByTieringCents(gbPerDay, coldDays, hotCentsPerGb, coldCentsPerGb) {
  return gbPerDay * coldDays * (hotCentsPerGb - coldCentsPerGb);
}

